import { isAnonymousUserId } from '../auth/anonymous-identity';

/**
 * Namespaces of storage keys. Every key is generated by the server; callers never choose one.
 * - `uploads/...`: multipart uploads used as job inputs, including every upload of an anonymous caller. They have no
 *   owner and are reachable by anyone holding the key (capability semantics). A key never names a client address.
 * - `conversions/<userId>/...`: synchronous API outputs owned by that user.
 * - `results/<jobId>/...`: queue job outputs, owned by the job's user when the job has one.
 */
export type StorageKeyNamespace =
  | { namespace: 'upload' }
  | { namespace: 'user-conversion'; userId: string }
  | { namespace: 'job-result'; jobId: string }
  | { namespace: 'other' };

const UPLOAD_KEY_PREFIX = 'uploads/';
const INLINE_INPUT_KEY = 'inline';
const INLINE_INPUT_KEY_PREFIX = 'inline:';
const USER_CONVERSION_KEY_PATTERN = /^conversions\/([^/]+)\//;
const JOB_RESULT_KEY_PATTERN = /^results\/([^/]+)\//;

/** Whether a key is in the ownerless multipart upload namespace. */
export function isUploadKey(key: string): boolean {
  return key.startsWith(UPLOAD_KEY_PREFIX);
}

/**
 * Whether a graph node's `storageKey` is the placeholder the server writes for an input that came in the request body
 * (`inline`, or `inline:<filename>`) and not a stored file. A key that only begins with "inline" is a stored key.
 */
export function isInlineInputKey(key: string): boolean {
  return key === INLINE_INPUT_KEY || key.startsWith(INLINE_INPUT_KEY_PREFIX);
}

/**
 * The key of a new multipart upload named `uniqueName`: under `conversions/<owner>/` for an account, and in the
 * ownerless upload namespace for an anonymous caller or none, so that no key carries an anonymous identity.
 */
export function multipartUploadKey(ownerUserId: string | undefined, uniqueName: string): string {
  return ownerUserId && !isAnonymousUserId(ownerUserId) ? `conversions/${ownerUserId}/${uniqueName}` : `${UPLOAD_KEY_PREFIX}${uniqueName}`;
}

export function classifyStorageKey(key: string): StorageKeyNamespace {
  if (isUploadKey(key)) {
    return { namespace: 'upload' };
  }

  const userConversion = USER_CONVERSION_KEY_PATTERN.exec(key);
  if (userConversion) {
    return { namespace: 'user-conversion', userId: userConversion[1] };
  }

  const jobResult = JOB_RESULT_KEY_PATTERN.exec(key);
  if (jobResult) {
    return { namespace: 'job-result', jobId: jobResult[1] };
  }

  return { namespace: 'other' };
}
